claim=intro('CLAIM HELP','A repair plan.<br><span>A clearer next step.</span>','If your RV has been damaged, start by gathering the details and calling our shop to discuss a damage evaluation.')+f'''<section class="section"><div class="container service-details"><div><p class="eyebrow">GETTING STARTED</p><h2>From the first call<br>to the repair.</h2><ol class="process"><li><h3>Gather your information</h3><p>Have your RV’s year, make, model, and VIN available, along with photos of the damage and any estimate already prepared.</p></li><li><h3>Contact your insurance company</h3><p>Report the incident and obtain your claim number and adjuster contact information. Ask your insurer about the next steps for your claim.</p></li><li><h3>Call AAA RV</h3><p>We will discuss your damage evaluation, repair plans, and appointment details. Your estimate is provided at no charge when AAA RV completes the approved repairs.</p></li><li><h3>Review the repair plan</h3><p>Our team can work with your adjuster on repair details. Coverage decisions belong to the insurer; repair authorization and scheduling are discussed with you.</p></li></ol><h2>Have these details ready.</h2>{checklist(['Your name and contact number','RV year, make, model, and VIN','Insurance company and claim number','Adjuster name and contact information','Photos and existing repair estimates','Incident date and a description of the damage'])}</div><aside class="estimate-card"><span class="small-label">YOUR ESTIMATE &amp; REPAIRS</span><h3>{e(ESTIMATE_BENEFIT)}</h3><p>{e(ESTIMATE_TERMS)}</p>{call('Call the shop')}<a class="text-link" href="{{{{R}}}}collision-repair/">Collision repair services {icon('arrow')}</a></aside></div></section>'''
page('claim-help','RV Claim Help','Prepare for an RV damage evaluation with claim details, photos, and a call to AAA RV. No estimate charge when we complete the approved repairs.',claim,'claim-help')

about=intro('ABOUT AAA RV','Craftsmanship<br><span>at our core.</span>','A local RV repair shop with roots in fiberglass work and a focus on the details that matter.')+f'''<section class="section"><div class="container craft-grid"><div class="craft-visual"><img src="{{{{R}}}}assets/shop.jpg" width="533" height="400" loading="lazy" alt="Historic Triple A Fiberglass Repair sign from the company’s photo collection"><div class="photo-caption">OUR ROOTS · AAA FIBERGLASS</div></div><div><p class="eyebrow">OUR STORY</p><h2>From fiberglass repair<br>to complete RV care.</h2><p>AAA’s story began with fiberglass work and the Kringlen family. What started as a small repair operation grew into a shop equipped for RV collision repairs, paint, restoration, and everyday service.</p><p>Today, AAA RV Collision &amp; Service serves RV owners from our location at 10519 S. Sunnylane in Oklahoma City. We work on motorhomes, fifth wheels, and travel trailers, inside and out.</p><p>Our approach is straightforward: pay attention to the details, talk through the work, and take pride in the finished repair.</p><a class="text-link" href="{{{{R}}}}rv-services/">Explore what we do {icon('arrow')}</a></div></div></section><section class="light-band"><div class="container">{heading('WHAT MATTERS HERE','The details.<br>The workmanship.<br><span>The people.</span>','From the structure underneath to the final finish, each part of a repair deserves attention. We offer a lifetime workmanship guarantee; ask our team about coverage for your specific repair.')}<div class="about-links"><a href="{{{{R}}}}gallery/">See our work {icon('arrow')}</a><a href="{{{{R}}}}claim-help/">Get claim help {icon('arrow')}</a><a href="{{{{R}}}}join-our-team/">Join our team {icon('arrow')}</a></div></div></section>'''
page('about','About AAA RV','Learn about AAA RV Collision & Service, our fiberglass repair roots, and our Oklahoma City shop.',about,'about')

gallery=intro('OUR WORK','Real repairs.<br><span>From our shop.</span>','A selection of collision, paint, roof, and restoration projects from AAA RV’s existing repair gallery.')+'''<section class="section"><div class="container">'''+heading('COLLISION REPAIR','Before &amp; after.')+'''<div class="comparison">'''+''.join(f'<figure><a href="{{{{R}}}}assets/{name}.jpg" target="_blank" rel="noopener" aria-label="Open {label.lower()} collision photo"><img src="{{{{R}}}}assets/{name}.jpg" alt="{alt}" width="800" height="600" loading="lazy"></a><figcaption>{label} · COLLISION REPAIR</figcaption></figure>' for name,label,alt in [('collision-before','BEFORE','Impact damage to the side of a motorhome before repair'),('collision-after','AFTER','Motorhome side after collision repairs')])+'''</div><div class="gallery-grid">'''+''.join(f'<figure><a href="{{{{R}}}}assets/{name}.jpg" target="_blank" rel="noopener" aria-label="Open {label.lower()} photo"><img src="{{{{R}}}}assets/{name}.jpg" alt="{alt}" width="600" height="450" loading="lazy"></a><figcaption>{label}</figcaption></figure>' for name,label,alt in [('paint-shop','Paint preparation','Motorhome masked for refinishing in the workshop'),('graphics-before','Graphics restoration · before','RV front with original graphics before restoration'),('water-before','Water damage · before','RV interior affected by water damage'),('water-after','Water damage · restoration','An interior restoration example from the water damage gallery'),('delamination-after','Delamination repair · after','RV sidewall after delamination repair'),('roof-repair','Roof replacement · in progress','Exposed RV roof during replacement')])+'''</div><p class="gallery-note">Select a photo to open the original image in a new tab.</p></div></section>'''
page('gallery','RV Repair Gallery','See examples of AAA RV collision repairs, paint preparation, water damage restoration, and roof replacement.',gallery,'gallery')

contact=intro('CONTACT','Let’s talk<br><span>about your RV.</span>','Call the shop to discuss your repair, ask about service, or arrange an appointment.')+f'''<section class="section contact-section"><div class="container contact-grid"><div class="contact-main"><p class="eyebrow">CALL AAA RV</p><a class="big-phone" href="{PHONE}">(405) 634-1429</a><p>Monday–Friday · 8 AM–5 PM</p><hr><h2>Visit the shop.</h2><address>AAA RV Collision &amp; Service<br>10519 S. Sunnylane<br>Oklahoma City, OK 73160</address><p>Near SE 104th Street &amp; S. Sunnylane.<br>Please call to arrange your visit or drop-off.</p><a class="button dark" href="{MAP}" target="_blank" rel="noopener">{icon('pin')} Get directions</a></div><div class="contact-prep"><p class="eyebrow">MAKE YOUR CALL COUNT</p><h2>A few details<br>help us get started.</h2>{checklist(['Your RV’s year, make, and model','The repair or maintenance you need','When the problem started, if applicable','Your travel plans or timing','Claim number and adjuster information, if applicable'])}<div class="online-option"><h3>Prefer to send a request online?</h3><p>Tell us about your RV and the work you need on our dedicated service request page, or use the form below.</p><a class="text-link" href="{{{{R}}}}request-service/">Request service online {icon('arrow')}</a></div></div></div></section><section class="section work-request-section" id="work-order-request"><div class="container"><p class="eyebrow">START YOUR REQUEST</p><h2>Request service online.</h2><p class="request-intro">Tell us about your RV and the work you need. Our team will follow up about scheduling. <a href="#estimate-policy">Review our estimate policy.</a></p><iframe id="shopmonkey-work-request" title="AAA RV work order request form" src="{BOOK}" width="100%" height="700" frameborder="0" loading="lazy"></iframe><p class="request-fallback">Having trouble with the form? <a href="{BOOK}" target="_blank" rel="noopener">Open the work order request form in a new tab {icon('arrow')}</a> or <a href="{PHONE}">call (405) 634-1429</a>.</p></div></section><section class="estimate-section" id="estimate-policy"><div class="container estimate-grid"><div><p class="eyebrow">QUOTES &amp; ESTIMATES</p><h2>Our estimate<br>policy.</h2><p>Know what to expect before you bring your RV in.</p></div><div><article><span class="small-label">DAMAGE EVALUATIONS</span><h3>{e(ESTIMATE_HEADLINE)}</h3><p>{e(ESTIMATE_TERMS)}</p><p>For example, an estimate fee applies if you choose to keep the repair funds or have the repairs completed elsewhere. Call us to discuss your plans and any applicable fee before your evaluation.</p></article><article><span class="small-label">SERVICE &amp; MAINTENANCE</span><h3>Free quotes for service and maintenance.</h3><p>Tell us the service or maintenance item you need. When an unknown issue requires troubleshooting, diagnostic labor may be necessary.</p></article></div></div></section><section class="section"><div class="container narrow">{heading('COMMON QUESTIONS','Before your visit.')}{faqs([('Will I pay for an estimate if AAA RV repairs my RV?','No. When AAA RV completes the repairs in your approved estimate, there is no estimate charge.'),('When does an estimate fee apply?','An estimate fee applies if we prepare an estimate and you choose not to have the approved repairs completed at AAA RV, such as keeping the repair funds or having the work done elsewhere. Call us to discuss the applicable fee before your evaluation.'),('What qualifies for a free quote?','Free quotes are available for service and maintenance related items. Finding the cause of an unknown problem may require diagnostic labor.'),('Do I need to call before bringing my RV?','Please call the shop to arrange your appointment or drop-off and confirm what information to bring.'),('Do you work on motorhomes and towable RVs?','We work on motorhomes, fifth wheels, and travel trailers. Motorhome engine and transmission repairs are outside our service scope.'),('Can you help with an insurance repair?','Yes. Bring your claim number, adjuster contact information, and any estimate or photos you already have. We can discuss the evaluation and repair process with you.')])}</div></section>'''
page('contact','Contact & Estimate Policy','Call AAA RV at (405) 634-1429. 10519 S. Sunnylane, Oklahoma City. Monday–Friday, 8 AM–5 PM. Learn about estimates and repairs at AAA RV.',contact,'contact')

resources=intro('RV RESOURCES','Useful information.<br><span>For the road ahead.</span>','A focused collection of service guidance, claim preparation, and outside RV resources.')+f'''<section class="section"><div class="container resource-grid"><article><span class="small-label">AAA RV</span><h2>Plan your service.</h2><p>Find maintenance, winterization, system checks, and the other services available at our shop.</p><a class="text-link" href="{{{{R}}}}rv-services/">Explore our services {icon('arrow')}</a></article><article><span class="small-label">AAA RV</span><h2>Prepare for a claim.</h2><p>See what information to gather before calling about collision or damage repairs.</p><a class="text-link" href="{{{{R}}}}claim-help/">Claim help {icon('arrow')}</a></article><article><span class="small-label">OUTSIDE RESOURCE</span><h2>RV Education 101</h2><p>RV education and owner information. This link takes you to an independent website.</p><a class="text-link" href="https://rveducation101.com/" target="_blank" rel="noopener">Visit RV Education 101 {icon('arrow')}</a></article><article><span class="small-label">OUTSIDE RESOURCE</span><h2>RV Trader</h2><p>Browse motorhomes, fifth wheels, and travel trailers on an independent RV marketplace.</p><a class="text-link" href="https://www.rvtrader.com/" target="_blank" rel="noopener">Visit RV Trader {icon('arrow')}</a></article></div></section>'''
page('links','RV Resources','Find AAA RV service information, claim preparation guidance, and RV owner resources.',resources)

careers=intro('JOIN OUR TEAM','Take pride<br><span>in your work.</span>','Interested in working with AAA RV? We value quality workmanship, customer service, and teamwork.')+f'''<section class="section"><div class="container service-details"><div><p class="eyebrow">WORK AT AAA RV</p><h2>Let’s start<br>a conversation.</h2><p>Call to ask about current opportunities in collision repair, fiberglass, paint, RV service, or shop support. Tell us about your experience and the kind of work you are looking for.</p><p>You may also mail your résumé to:</p><address>AAA RV Collision &amp; Service<br>10519 S. Sunnylane<br>Oklahoma City, OK 73160</address></div><aside class="estimate-card"><span class="small-label">ASK ABOUT OPPORTUNITIES</span><h3>Call the shop.</h3><p>Monday–Friday<br>8 AM–5 PM</p>{call()}<p>Call to confirm current openings.</p></aside></div></section>'''
page('join-our-team','Careers at AAA RV','Call AAA RV Collision & Service to ask about current career opportunities in Oklahoma City.',careers)

request_service=f'''<section class="request-page work-request-section" id="work-order-request"><div class="container"><p class="breadcrumb"><a href="{{{{R}}}}">Home</a> / REQUEST SERVICE</p><div class="request-page-heading"><div><p class="eyebrow">LET’S GET STARTED</p><h1>Request <span>service.</span></h1><p class="request-intro">Tell us about your RV and the work you need. Our team will follow up to discuss the next steps and arrange scheduling.</p></div><aside class="request-help"><p>Have a quick question?</p><a href="{PHONE}">{icon('phone')} Call (405) 634-1429</a><a href="{TEXT}">{icon('message')} Text us</a><span>Monday–Friday · 8 AM–5 PM</span></aside></div><div class="request-form-wrap"><iframe id="shopmonkey-work-request" title="AAA RV work order request form" src="{BOOK}" width="100%" height="700" frameborder="0" loading="eager"></iframe></div><div class="request-page-notes"><p>Submitting a request does not confirm an appointment. Our team will contact you about availability. <a href="{{{{R}}}}contact/#estimate-policy">Review our estimate policy.</a></p><p class="request-fallback">Having trouble with the form? <a href="{BOOK}" target="_blank" rel="noopener">Open it in a new tab {icon('arrow')}</a>.</p></div></div></section>'''
page('request-service','Request RV Service in Oklahoma City','Request RV collision repair, maintenance, or service from AAA RV in Oklahoma City. Send your vehicle details and service needs using our online work request form.',request_service,'request-service')

page('404','Page Not Found','Find AAA RV services, contact details, or return to the homepage.',intro('PAGE NOT FOUND','Let’s get you<br><span>back on track.</span>','The page you are looking for could not be found.')+'<section class="section"><div class="container"><a class="button gold" href="'+BASE+'/">Go to homepage</a></div></section>')
# GitHub Pages serves 404.html at the originally requested path. Absolute assets keep it usable at any depth.
notfound=(ROOT/'404/index.html').read_text().replace('../',BASE+'/')
(ROOT/'404.html').write_text(notfound)
(ROOT/'404/index.html').unlink();(ROOT/'404').rmdir()
(ROOT/'.nojekyll').touch()
(ROOT/'robots.txt').write_text('User-agent: *\nDisallow: /\n')
print(f'Generated {len(PAGES)-1} pages and 404.html.')
